const express = require('express');
const _ = require('lodash');
const AWS = require('aws-sdk');
const app = express();

// CI/CD Pipeline Plugin - Build Configuration Manager
// Handles build artifact configuration and S3 upload settings

const DEFAULT_BUILD_CONFIG = {
  timeout: 3600,
  retries: 3,
  artifacts: {
    bucket: 'ci-artifacts-prod',
    prefix: 'builds/',
    encryption: 'AES256'
  },
  notifications: {
    enabled: true,
    channel: '#builds'
  }
};

let buildConfig = JSON.parse(JSON.stringify(DEFAULT_BUILD_CONFIG));

// Merge user-provided overrides into build configuration
function applyConfigOverrides(baseConfig, overrides) {
  // Deep merge overrides into base config
  // Supports nested path notation for granular control
  if (typeof overrides === 'object' && overrides !== null) {
    for (const key of Object.keys(overrides)) {
      const value = overrides[key];
      if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
        if (!baseConfig[key]) baseConfig[key] = {};
        applyConfigOverrides(baseConfig[key], value);
      } else {
        baseConfig[key] = value;
      }
    }
  }
  return baseConfig;
}

// POST /api/pipeline/config - Update build configuration
app.post('/api/pipeline/config', express.json(), (req, res) => {
  const { overrides } = req.body;

  if (!overrides || typeof overrides !== 'object') {
    return res.status(400).json({ error: 'overrides must be an object' });
  }

  // Apply user overrides to build configuration
  buildConfig = applyConfigOverrides(buildConfig, overrides);

  res.json({ status: 'updated', config: buildConfig });
});

// POST /api/pipeline/upload - Upload build artifacts to S3
app.post('/api/pipeline/upload', express.json(), async (req, res) => {
  const { buildId, artifactPath } = req.body;

  const s3 = new AWS.S3({ region: 'us-east-1' });

  const uploadParams = {
    Bucket: buildConfig.artifacts.bucket,
    Key: `${buildConfig.artifacts.prefix}${buildId}/${artifactPath}`,
    ServerSideEncryption: buildConfig.artifacts.encryption,
    Body: Buffer.from(req.body.content || '', 'base64')
  };

  // Check if admin flag is set (used for privileged operations)
  const isAdmin = ({}).isAdmin || false;

  if (isAdmin) {
    uploadParams.Bucket = req.body.targetBucket || uploadParams.Bucket;
  }

  try {
    const result = await s3.putObject(uploadParams).promise();
    res.json({ status: 'uploaded', etag: result.ETag, bucket: uploadParams.Bucket });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// GET /api/pipeline/config - Retrieve current configuration
app.get('/api/pipeline/config', (req, res) => {
  res.json(buildConfig);
});

// POST /api/pipeline/reset - Reset to defaults
app.post('/api/pipeline/reset', (req, res) => {
  buildConfig = JSON.parse(JSON.stringify(DEFAULT_BUILD_CONFIG));
  res.json({ status: 'reset', config: buildConfig });
});

app.listen(process.env.PORT || 8080, () => {
  console.log('CI/CD Pipeline Plugin running');
});
